&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Saadet Partisi Genel Başkanı Mahmut Arıkan&amp;rsquo;ın Grup Toplantısı Konuşma Metni&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Değerli Arkadaşlar;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;İki g&amp;uuml;n &amp;ouml;nce 24 Kasım &amp;Ouml;ğretmenler G&amp;uuml;n&amp;uuml; idi. Başta kendi ilkokul &amp;ouml;ğretmenim&amp;nbsp;Ayten İlbasmış hocam&amp;nbsp;olmak&amp;nbsp;&amp;uuml;zere,&amp;nbsp;t&amp;uuml;m&amp;nbsp;&amp;ouml;ğretmenlerimizin g&amp;uuml;n&amp;uuml;n&amp;uuml; bir kez daha kutluyorum.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;Ouml;ğretmenler G&amp;uuml;n&amp;uuml; vesilesiyle aynı&amp;nbsp;dersi, aynı&amp;nbsp;s&amp;uuml;rede ve aynı kalitede anlattığı halde&amp;nbsp; teneff&amp;uuml;s&amp;nbsp;saatinde&amp;nbsp;&amp;ouml;ğretmenler odasında;&amp;nbsp;&amp;ouml;ğretmenlerin; kadrolu&amp;nbsp;&amp;ouml;ğretmen,&amp;nbsp;s&amp;ouml;zleşmeli&amp;nbsp;&amp;ouml;ğretmen ve&amp;nbsp;&amp;uuml;cretli&amp;nbsp;&amp;ouml;ğretmen adı&amp;nbsp;altında farklı stat&amp;uuml;lerle ve&amp;nbsp;farklı&amp;nbsp;hak edişlerle kategorize edilmelerinin yanlışlığını&amp;nbsp;bir kez daha ifade ediyorum.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;Ouml;zel sekt&amp;ouml;r &amp;ouml;ğretmenlerinin&amp;nbsp;de taleplerini buradan yineliyorum.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bu&amp;nbsp;&amp;ouml;ğretmenlerimiz haklı olarak, 2014&amp;rsquo;te kaldırılan taban maaşının geri&amp;nbsp;getirilmesini, Kamuda&amp;nbsp;&amp;ccedil;alışan bir&amp;nbsp;&amp;ouml;ğretmen ile aynı&amp;nbsp;&amp;ouml;zl&amp;uuml;k&amp;nbsp;haklarına sahip olmayı, mevsimlik&amp;nbsp;tarım iş&amp;ccedil;isi gibi değil, insan onuruna yakışır bir vaziyette iş g&amp;uuml;vencesi ile &amp;ccedil;alışmayı,&amp;nbsp;diğer&amp;nbsp;bir &amp;ccedil;ok meslek ile birlikte&amp;nbsp;10&amp;rsquo;nulu iş kolunda&amp;nbsp;yer almayı değil,&amp;nbsp;sadece&amp;nbsp;eğitimcilerden oluşan&amp;nbsp;bir iş kolunda yer almayı ve sendikalaşma hakkını istiyorlar.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Atanamayan&amp;nbsp;&amp;ouml;ğretmenlerimizin, m&amp;uuml;lakat&amp;nbsp;mağduru olan &amp;ouml;ğretmenlerimizin ve&amp;nbsp;KHK mağduru &amp;ouml;ğretmenlerimizin de m&amp;uuml;cadelelerini&amp;nbsp;desteklediğimizi buradan&amp;nbsp;bir kez daha deklare ediyorum.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;TER&amp;Ouml;RS&amp;Uuml;Z T&amp;Uuml;RKİYE &amp;ndash; YAŞANABİLİR T&amp;Uuml;RKİYE&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Değerli arkadaşlar;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Hepinizin malumu T&amp;uuml;rkiye, bir yıldan uzun bir s&amp;uuml;redir &amp;ldquo;Ter&amp;ouml;rs&amp;uuml;z T&amp;uuml;rkiye&amp;rdquo; adı verilen s&amp;uuml;reci konuşuyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;S&amp;ouml;zlerimin başında şunu belirtmek istiyorum: Saadet Partisi, sadece &amp;uuml;lkemizde değil&amp;nbsp;&amp;nbsp;t&amp;uuml;m yery&amp;uuml;z&amp;uuml;nde adaletin ve barışın hakim olması i&amp;ccedil;in &amp;ccedil;alışan kadroların partisidir.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bizim kadrolarımız bizim gibi inansın ya da inanmasın M&amp;uuml;sl&amp;uuml;man olsun ya da olmasın 8 milyarı aşkın insanın her birinin&amp;nbsp;insan&amp;nbsp;onuruna yakışır bir yaşam s&amp;uuml;rmesi i&amp;ccedil;in m&amp;uuml;cadele ederler.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Saadet Partisiyle ırk&amp;ccedil;ılığın, mezhep&amp;ccedil;iliğin ya da b&amp;ouml;lgeciliğin yan yana gelmesi asla m&amp;uuml;mk&amp;uuml;n değildir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Şunu da hatırlatmak isterim: Saadet Partisi, bu &amp;uuml;lkede ve bu b&amp;ouml;lgede &amp;ldquo;adil bir d&amp;uuml;zenin&amp;rdquo; kurulması i&amp;ccedil;in ter&amp;ouml;rs&amp;uuml;z bir T&amp;uuml;rkiye i&amp;ccedil;in defalarca bedel &amp;ouml;demiş kadroların partisidir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;YAKIN BİR &amp;Ouml;RNEK: SURİYE&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Biz Saadet Partisi olarak, t&amp;uuml;m samimiyetimizle b&amp;ouml;lgede bir istikrar, bir kardeşlik olsun istiyoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bu kardeşliğin de; Kan d&amp;ouml;kerek değil dil d&amp;ouml;kerek, ter d&amp;ouml;kerek inşa edileceğine inanıyoruz. Bakınız komşumuz Suriye&amp;rsquo;den bahsetmek, resmin b&amp;uuml;y&amp;uuml;ğ&amp;uuml;n&amp;uuml; g&amp;ouml;stermek istiyorum. Suriye&amp;rsquo;de yıllardır bitmeyen bir kargaşa var. &amp;Uuml;lkede T&amp;uuml;rkmenler, S&amp;uuml;nni Araplar, Nusayriler, K&amp;uuml;rtler, D&amp;uuml;rziler,&amp;nbsp;Ezidiler var.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Gelinen noktada;&amp;nbsp;b&amp;ouml;lgede&amp;nbsp;birbirleriyle komşu olan bu toplulukların hepsi hem&amp;nbsp;ABD ile hem de İsrail ile temas halinde. ABD ve İsrail ile temas halinde olan bu toplulukların; birbirleriyle samimi ve i&amp;ccedil;ten bir temasları yok, temasa ge&amp;ccedil;ecek olurlarsada bu ABD ve İsrail aracılığıyla oluyor.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Kadim komşular birbirleriyle masaya ABD ve İsrail olmadan oturamıyorlar. Ne ABD ne de İsrail, b&amp;ouml;lgemizde barışın h&amp;acirc;kim olmasını istemiyorlar.&amp;nbsp;Sadece kendi &amp;ccedil;ıkarlarını &amp;ouml;nceliyorlar. B&amp;ouml;lge&amp;nbsp;kaynakları &amp;uuml;zerinde diledikleri tasarrufta bulunmanın&amp;nbsp;planlarını&amp;nbsp;yapıyorlar.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;BAZI ŞEYLER İ&amp;Ccedil;İN ADA SEFERİ D&amp;Uuml;ZENLEMEYE GEREK YOK!&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Başta bu ger&amp;ccedil;eklik den dolayı bir&amp;ccedil;ok şeye rağmen bizler; Milli Dayanışma, Kardeşlik ve Demokrasi Komisyonu&amp;rsquo;nda yer aldık.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Milli Birlik ve Dayanışma Komisyonunun &amp;ccedil;alışmalarına sağlıklı devam edebilmesi i&amp;ccedil;in; Biz t&amp;uuml;m varlığımızla, Anayasa Mahkemesinin ve Avrupa İnsan Hakları Mahkemesi&amp;rsquo;nin kararlarının tanınmasını istiyoruz. K&amp;uuml;rt Meselesinin &amp;ccedil;&amp;ouml;z&amp;uuml;m&amp;uuml;n&amp;uuml; istiyoruz. Hak ve &amp;ouml;zg&amp;uuml;rl&amp;uuml;klerin &amp;ouml;n&amp;uuml;ndeki kısıtlamaların kaldırılmasını istiyoruz. Kayyım rejiminin son bulması istiyoruz. KHK mağduriyetlerinin giderilmesini istiyoruz. Harp okulu &amp;ouml;ğrencilerinin serbest kalmasını istiyoruz. Barış akademisyenlerinin k&amp;uuml;rs&amp;uuml;lerine kavuşmasını istiyoruz. Hukuka rağmen tahliye edilmeyen Can Atalay&amp;rsquo;ın, Osman Kavala&amp;rsquo;nın, Selahattin Demirtaş&amp;rsquo;ın &amp;ouml;zg&amp;uuml;rl&amp;uuml;klerine kavuşmasını istiyoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;B&amp;uuml;t&amp;uuml;n bu adımların atılması i&amp;ccedil;in iktidarın ada seferleri d&amp;uuml;zenleyip durmasına gerek yok.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Biz şunu soruyoruz: T&amp;uuml;rkiye&amp;rsquo;nin ger&amp;ccedil;ek bir hukuk devleti olması i&amp;ccedil;in ka&amp;ccedil; sefer yapmak gerekir?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Anayasa Mahkemesinin kararlarını uygulamak i&amp;ccedil;in hangi adaya gitmek gerekir?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Hak ve &amp;ouml;zg&amp;uuml;rl&amp;uuml;kler &amp;uuml;zerindeki kısıtlamaları kaldırmanız i&amp;ccedil;in daha ka&amp;ccedil; komisyon kurmak gerekir?&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;KHK&amp;rsquo;lıların, akademisyenlerin, gazetecilerin mağduriyetlerini gidermek i&amp;ccedil;in hangi adada olmaları gerekir?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;A&amp;ccedil;lık sınırının altında yaşayan milyonların, seslerini duyurmaları i&amp;ccedil;in hangi adaya demir atmaları gerekir?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Asgari &amp;uuml;creti a&amp;ccedil;lık sınırının &amp;uuml;st&amp;uuml;ne taşımak i&amp;ccedil;in hangi adaya yelken a&amp;ccedil;mak gerekir?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bizim beklentimiz ve talebimiz, s&amp;uuml;recin&amp;nbsp;yol haritasının ortaya konulması,&amp;nbsp; gerekli&amp;nbsp;d&amp;uuml;zenlemelerin hak ve adalet &amp;ccedil;er&amp;ccedil;evesinde yapılması ve&amp;nbsp;hukuka&amp;nbsp;riayet edilmesidir.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Biz bulunduğumuz her platformda t&amp;uuml;m mağdurların adalet arayışını g&amp;uuml;ndem yapmaya devam edeceğiz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Kadınların,&amp;nbsp;yaşlıların&amp;nbsp;ve&amp;nbsp;gen&amp;ccedil;lerin&amp;nbsp;haklı beklentilerini g&amp;uuml;ndem yapacağız. Emeklinin, emek&amp;ccedil;inin, esnafın&amp;nbsp;ve &amp;ccedil;ift&amp;ccedil;inin&amp;nbsp;geleceğe dair umutlarını yeşertmeyi g&amp;uuml;ndem yapacağız.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;Uuml;lkemizde, b&amp;ouml;lgemizde ve d&amp;uuml;nyada barışın tesisi i&amp;ccedil;in &amp;uuml;zerimize ne d&amp;uuml;ş&amp;uuml;yorsa yapmaktan imtina etmeyeceğiz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Ancak iktidara baktığımızda &amp;ouml;yle g&amp;ouml;r&amp;uuml;n&amp;uuml;yor ki b&amp;uuml;t&amp;uuml;n muhalefeti kendi keyfiliğini konsolide etmenin aracı yapmaya &amp;ccedil;alışıyor. K&amp;uuml;rt meselesini &amp;ccedil;&amp;ouml;zmenin değil, muhalefeti par&amp;ccedil;alamanın gayretinde olduğuna dair bir izlenim veriyor. Ve en &amp;ouml;nemlisi başka hi&amp;ccedil;bir g&amp;uuml;ndemin konuşulmasını istemiyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

