&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;TER&amp;Ouml;RS&amp;Uuml;Z T&amp;Uuml;RKİYE KONUŞULURKEN&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bir ger&amp;ccedil;eğin de altını &amp;ccedil;izmek zorundayız: İmralı konuşulurken, T&amp;uuml;rkiye&amp;rsquo;nin diğer b&amp;uuml;t&amp;uuml;n temel meseleleri adeta sessizce rafa kaldırılıyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bug&amp;uuml;n; &amp;uuml;lkenin ekonomisi &amp;ccedil;&amp;ouml;k&amp;uuml;yor, gelir dağılımındaki u&amp;ccedil;urumlar artıyor, yoksulluk derinleşiyor, d&amp;uuml;zen &amp;ccedil;&amp;uuml;r&amp;uuml;meye devam ediyor.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;GELİR DAĞILIMDA ADALETSİZLİK ARTMAYA DEVAM EDİYOR&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Mesela n&amp;uuml;fusumuzun &amp;ouml;nemli bir b&amp;ouml;l&amp;uuml;m&amp;uuml;; artan eşitsizlikten ve derin yoksulluktan nasibini alırken bu faize dayalı s&amp;ouml;m&amp;uuml;r&amp;uuml; d&amp;uuml;zeninin &amp;ccedil;arkları d&amp;ouml;nmeye devam ediyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Alın teri ve el emeği ile ge&amp;ccedil;inen iş&amp;ccedil;imiz, &amp;ouml;zel sekt&amp;ouml;r &amp;ouml;ğretmenlerimiz, tarım &amp;uuml;reticimiz, hayvan &amp;uuml;reticimiz, k&amp;uuml;&amp;ccedil;&amp;uuml;k esnafımız, sanayi esnafımız can &amp;ccedil;ekişiyor.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;D&amp;uuml;şlerini &amp;ccedil;oktan yitiren &amp;ccedil;ocuklarımız sigortasız &amp;ccedil;alıştırıldıkları parf&amp;uuml;m fabrikalarında can veriyor.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Kırk yıl, k&amp;ouml;le gibi &amp;ccedil;alıştıkları halde yine de bir birikimi olmayan insanlarımız emekliliklerinde taş ocaklarında g&amp;ouml;&amp;ccedil;&amp;uuml;k altında kalıyor. Ama bu &amp;uuml;lkenin mutlu azınlığı olan &amp;ldquo;tefeciler&amp;rdquo; kazanmaya devam ediyor.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Piramidin tepesinde servet, tabanında sefalet birikiyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bakınız; bankaların Eyl&amp;uuml;l ayı itibariyle net k&amp;acirc;rı 669 milyar T&amp;uuml;rk Lirası. Bankaların en &amp;ccedil;ok faiz geliri elde ettiği kalem ticari ya da kurumsal krediler değil! Bankaların k&amp;acirc;rının 517 milyar T&amp;uuml;rk Lirası t&amp;uuml;ketici kredilerinden olmuş.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Yani insanımız; &amp;ccedil;ocuğuna ayakkabı alabilmek i&amp;ccedil;in, evine ekmek g&amp;ouml;t&amp;uuml;rebilmek, kirasını &amp;ouml;deyebilmek i&amp;ccedil;in faizle bankalara bor&amp;ccedil;lanmış. Yılbaşında &amp;ldquo;takipteki&amp;rdquo; t&amp;uuml;ketici kredisi miktarı 116 milyar T&amp;uuml;rk lirası iken Eyl&amp;uuml;l ayı itibariyle bu rakam 222 milyar T&amp;uuml;rk lirasına &amp;ccedil;ıkmış.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;İnsanımızın &amp;ouml;nemli bir kısmı bug&amp;uuml;n yaşama tutunabilmek i&amp;ccedil;in yarınını bankalara teslim ederken; T&amp;uuml;rkiye&amp;rsquo;nin en zenginleri servetlerini dolar bazında %52 artırmış. Bu rakamlara bakınca Mehmet Şimşek&amp;rsquo;in programı, bir konuda ger&amp;ccedil;ekten başarılı olmuş g&amp;ouml;z&amp;uuml;k&amp;uuml;yor! T&amp;uuml;rkiye, ge&amp;ccedil;tiğimiz yıl d&amp;uuml;nyanın dolar milyoneri en &amp;ccedil;ok artan &amp;uuml;lkesi oldu.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;KOKUŞMUŞ D&amp;Uuml;ZEN&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Değerli Arkadaşlar, Haksız kazan&amp;ccedil; ile servet belirli ellerde birikirken, sefalet geniş kitlelere yayılıyor. B&amp;ouml;yle oluncada toplumda &amp;ccedil;&amp;uuml;r&amp;uuml;me, bozulma, kokuşmuşluk -elbette- ka&amp;ccedil;ınılmaz oluyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Sadece son bir haftada yaşadıklarımızı d&amp;uuml;ş&amp;uuml;nelim. Seyahat i&amp;ccedil;in İstanbul&amp;rsquo;a gelen B&amp;ouml;cek Ailesi, al&amp;uuml;minyum fosfitten zehirlenerek&amp;nbsp;&amp;nbsp;g&amp;ouml;z g&amp;ouml;re g&amp;ouml;re yaşamdan koparıldı.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Adıyaman&amp;rsquo;da KYK yurdunda kalan 70 &amp;ouml;ğrenci akşam yemeğinin ardından rahatsızlanarak hastaneye kaldırıldı. İstanbul Esenyurt&amp;rsquo;ta Eren Yılgın adlı evladımız yediği tavuk d&amp;ouml;nerinin ardından kaldırıldığı hastanede yaşamını yitirdi. İstanbul Şişli&amp;rsquo;de 25 kişi gıda zehirlenmesi nedeniyle hastanelik oldu. Dışarıda bunlar olurken, i&amp;ccedil;eride yani cezaevlerinde de durum pek farklı değil. Sakarya A&amp;ccedil;ık Cezaevinde hazır konserve balık yedirilen 266 h&amp;uuml;k&amp;uuml;ml&amp;uuml; de hastanelik oldu.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Elbette &amp;ccedil;&amp;uuml;r&amp;uuml;m&amp;uuml;şl&amp;uuml;k sadece gıdalarla sınırlı değil! &amp;Uuml;lkemiz; ucuz &amp;ouml;l&amp;uuml;mler &amp;uuml;lkesi haline geldi. Sporumuz, bahis ve şikenin merkez &amp;uuml;ss&amp;uuml; haline geldi. Mahallelerde &amp;ccedil;eteler şiddet sa&amp;ccedil;ıyorlar, kadınlarımız, &amp;ccedil;ocuklarımız, insanımız sokaklarda g&amp;uuml;venle y&amp;uuml;r&amp;uuml;yemiyorlar, trafikte kaba kuvvet sıradan bir durum haline geldi. B&amp;uuml;t&amp;uuml;n bunlar olurken de Sayın Cumhurbaşkanı, &amp;ldquo;Bug&amp;uuml;n barış, huzur ve istikrar denince akla ilk T&amp;uuml;rkiye geliyor&amp;rdquo; diyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;HALK SAĞLIĞI (!)&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Değerli arkadaşlar;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;B&amp;ouml;cek Ailesi&amp;rsquo;nin bir otel odasında zehirlenerek &amp;ouml;lmesi ya da Eren Yılgın evladımızın yediği yiyecekten sonra yaşamını yitirmesi sadece denetimsizlikten kaynaklanan m&amp;uuml;nferit bir olay değildir!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Tablo &amp;ccedil;ok daha vahim. Yaşananlar, halk sağlığı y&amp;ouml;netiminin, koruyucu hekimliğin ve zehirle m&amp;uuml;cadele sisteminin &amp;ldquo;birlikte &amp;ccedil;&amp;ouml;kt&amp;uuml;ğ&amp;uuml;n&amp;uuml;n&amp;rdquo; resmidir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bunun elbette bir&amp;ccedil;ok nedeni var! Devlette ehliyet ve liyakatin ortadan kaldırılması bunun nedenidir. Partizanca atamalar bunun nedenidir.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

