&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;TRUMP&amp;rsquo;TAN BARIŞ G&amp;Uuml;VERCİNİ &amp;Ccedil;IKMAZ&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;Ccedil;apraşıklık bununla kalmıyor. Bu planın uygulanması i&amp;ccedil;in kurulacak &amp;ldquo;Barış Kurulu&amp;rdquo;nun başına da Trump&amp;rsquo;ın getirilmesi &amp;ouml;ng&amp;ouml;r&amp;uuml;l&amp;uuml;yor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bu tablo ortadayken, &amp;ldquo;Barış Planı&amp;rdquo;nı Trump&amp;rsquo;ın başkanlığında uygulamak; tilkiyi k&amp;uuml;mese bek&amp;ccedil;i yapmaktır!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Trump&amp;rsquo;ın Ukrayna i&amp;ccedil;in &amp;ouml;nerdiği planı hatırlayalım. &amp;ldquo;Savaşın durması i&amp;ccedil;in Ukrayna topraklarından vazge&amp;ccedil;sin&amp;rdquo; yaklaşımı barış değil, zorla sınır değiştirme teklifidir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Filistin&amp;rsquo;de mazlumun değil işgalin yanında duran, Ukrayna&amp;rsquo;da saldırıya uğrayanı değil saldırganı &amp;ouml;d&amp;uuml;llendiren, k&amp;uuml;resel krizlerde hukuku değil şahsi ajandasını &amp;ouml;nceleyen bir siyaset&amp;ccedil;inin d&amp;uuml;nyaya barış getirmesi m&amp;uuml;mk&amp;uuml;n değildir. Kısacası: Trump&amp;rsquo;dan barış g&amp;uuml;vercini &amp;ccedil;ıkmaz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;D&amp;Uuml;NYA&amp;rsquo;NIN &amp;ldquo;ADİL BİR D&amp;Uuml;ZENE&amp;rdquo; İHTİYACI VAR&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Değerli arkadaşlar!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;D&amp;uuml;nya&amp;rsquo;nın herhangi bir yerinde, Trump&amp;rsquo;a ihtiyacı yoktur. D&amp;uuml;nya&amp;rsquo;nın &amp;ldquo;Adil Bir D&amp;uuml;zene&amp;rdquo; ihtiyacı vardır. O zaman b&amp;uuml;t&amp;uuml;n krizlerimiz &amp;ccedil;&amp;ouml;z&amp;uuml;l&amp;uuml;r.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Ge&amp;ccedil;tiğimiz g&amp;uuml;nlerde; bir dizi temasta bulunmak &amp;uuml;zere Pakistan&amp;rsquo;daydım. D&amp;uuml;nyanın geleceğine dair, 47 &amp;uuml;lkenin katılımıyla ger&amp;ccedil;ekleştirilen toplantılara katıldık. Ve d&amp;uuml;n Pakistan&amp;rsquo;dan kucak dolusu sevgiyle ve bir&amp;ccedil;ok &amp;ouml;devle yurda d&amp;ouml;nd&amp;uuml;k.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bir &amp;ouml;nceki ay da yine aynı şekilde Malezya&amp;rsquo;daydım. Her iki &amp;uuml;lkede de g&amp;ouml;rd&amp;uuml;ğ&amp;uuml;m tablo &amp;ccedil;ok net: İhtiyacımız olan Trump&amp;rsquo;a bağlı &amp;ldquo;barış planları&amp;rdquo; değil, M&amp;uuml;sl&amp;uuml;man d&amp;uuml;nyanın kendi i&amp;ccedil;inde birlik oluşturmasıdır. Bu birlikten doğacak cesarete ihtiyacı vardır. Rahmetli Erbakan hocamızın &amp;ouml;nderliğinde kurulan, D-8 b&amp;ouml;yle cesur bir adımdı.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Yıllardır; &amp;ldquo;Şahsiyetli bir dış politika&amp;rdquo; derken aslında bunu kastediyorduk.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bug&amp;uuml;n d&amp;uuml;nyada, T&amp;uuml;rkiye&amp;rsquo;nin &amp;ldquo;şahsiyetli bir dış politika&amp;rdquo; izlemesi, İslam d&amp;uuml;nyasının bir araya gelmesi &amp;ldquo;Adil Bir D&amp;uuml;nya&amp;rdquo; i&amp;ccedil;in b&amp;uuml;y&amp;uuml;k bir &amp;ouml;neme sahiptir. Nitekim, b&amp;ouml;lgemizi ilgilendiren kararlar Amerika&amp;rsquo;nın &amp;ouml;nc&amp;uuml;l&amp;uuml;ğ&amp;uuml;nde, Şarm-el Şeyh&amp;rsquo;te değil; T&amp;uuml;rkiye&amp;rsquo;nin &amp;ouml;nc&amp;uuml;l&amp;uuml;ğ&amp;uuml;nde, Ankara&amp;rsquo;da alınmak zorundadır.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Biz bunu sağladığımızda; Gazze&amp;rsquo;de de, Keşmir&amp;rsquo;de de, Arakan&amp;rsquo;da da, Batı Şeria&amp;rsquo;da da&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;zulm&amp;uuml; durduracak en b&amp;uuml;y&amp;uuml;k g&amp;uuml;&amp;ccedil; by duruş ve bu birlik olacaktır.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

